void unlock_pagevec(struct pagevec *pvec, struct zone *zone) {
    int i;
    struct page *page;
    int unlock_count = 0;

    for (i = 0; i < pagevec_count(pvec); i++) {
        page = pvec->pages[i];

        if (PageLocked(page)) {
            unlock_page(page);
            unlock_count++;
        } else {
            put_page(page);
        }
    }

    for (i = 0; i < pagevec_count(pvec); i++) {
        page = pvec->pages[i];

        if (!PageLocked(page)) {
            put_page(page);
        } else {
            if (unlock_count) {
                spin_lock(&zone->lock);
                if (!PageLocked(page)) {
                    put_page(page);
                }
                spin_unlock(&zone->lock);
            }
        }
    }

    pagevec_reinit(pvec);
}

void unlock_pagevec(struct pagevec *pvec, struct zone *zone) {
    struct page *page;
    int i;

    for (i = 0; i < pagevec_count(pvec); i++) {
        page = pvec->pages[i];

        if (PageLocked(page)) {
            ClearPageLocked(page);
            unlock_page(page);
            zone->unlocked_pages++;
        } else {
            if (page_ref_count(page) > 1) {
                put_page(page);
            }
        }
    }

    for (i = 0; i < pagevec_count(pvec); i++) {
        page = pvec->pages[i];
        if (PageUptodate(page)) {
            putback_page(zone, page);
        }
    }
}

void pagevec_unlock(struct pagevec *pvec, struct zone *zone) {
    struct page *page;
    int i;

    for (i = 0; i < pvec->nr_pages; i++) {
        page = pvec->pages[i];

        if (PageLocked(page)) {
            UnlockPage(page);
            pvec->nr_locked--;
        }
    }

    for (i = 0; i < pvec->nr_pages; i++) {
        page = pvec->pages[i];

        if (!PageLocked(page)) {
            PutPagePin(page);
        }
    }

    for (i = 0; i < pvec->nr_pages; i++) {
        page = pvec->pages[i];

        if (PageFastPath(page)) {
            PutBackPageFastPath(page, zone);
        }
    }
}

void pagevec_unlock(struct pagevec *pvec, struct zone *zone) {
    int i;
    struct page *page;
    int unlocked = 0;

    for (i = 0; i < pvec->nr; i++) {
        page = pvec->pages[i];
        if (PageLocked(page)) {
            UnlockPage(page);
            unlocked++;
        }
    }

    for (i = 0; i < pvec->nr; i++) {
        page = pvec->pages[i];
        if (!PageLocked(page)) {
            page_cache_release(page);
        }
    }

    for (i = 0; i < pvec->nr; i++) {
        page = pvec->pages[i];
        if (!PageLocked(page)) {
            __pagevec_release(pvec, page);
        }
    }

    if (unlocked) {
        spin_lock(&zone->lock);
        zone->nr_pages_locked -= unlocked;
        spin_unlock(&zone->lock);
    }
}
